package com.smartproperty.platform.residentportal.controller;
import com.smartproperty.platform.residentportal.dto.*;import com.smartproperty.platform.residentportal.service.ResidentPortalService;import com.smartproperty.platform.residentportal.vo.ResidentPortalVO.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin/incidents") public class ResidentIncidentAdminController {private final ResidentPortalService s;public ResidentIncidentAdminController(ResidentPortalService x){s=x;}@GetMapping public List<IncidentVO> list(){return s.scopedIncidents();}@PatchMapping("/{id}/status")public void status(@PathVariable Long id,@Valid @RequestBody IncidentStatusRequest r){s.updateIncidentStatus(id,r);}}
